static void reveal(QWidget *control){
 require(control,"FK5 dynamics control absent");
 for(QWidget *parent=control;parent;parent=parent->parentWidget())if(auto *scroll=qobject_cast<QScrollArea *>(parent))scroll->ensureWidgetVisible(control);
 events();require(control->isVisible()&&control->isEnabled(),"FK5 dynamics control hidden or disabled");acceptanceView(*control);
}
